expressionFragments.discarded-short-circuit:
precision mediump float;
uniform bool gate;
float calls;
bool left() { calls += 1.; return gate; }
bool right() { calls += 2.; return true; }
void main() {
  calls = 0.;
  if (!gate) left() && right();
  if (!gate) left() || right();
  for (int i = 0; i < 2; ++i) left() && right();
  if (gate) right();
  gl_FragColor = calls == 6. ? vec4(0.,1.,0.,1.) : vec4(1.,0.,0.,1.);
}

expressionFragments.conditional-function-return:
precision mediump float;
uniform float offset;
vec2 choose(float f) { if (f > 0.) return vec2(-f, f + 1.); }
void main() {
  vec2 result = choose(2. + offset);
  gl_FragColor = result == vec2(-2., 3.) ? vec4(0.,1.,0.,1.) : vec4(1.,0.,0.,1.);
}
